// Isometric projection shared by the 3D scenes: x runs right-down, y left-down, z up.
function isoPoint(x: number, y: number, z = 0): [number, number] {
  return [131 + (x - y) * 0.866, 52 + (x + y) * 0.5 - z];
}

function iso(x: number, y: number, z = 0) {
  return isoPoint(x, y, z).join(" ");
}

// Matrices that lay a 24×24 icon at scale k on a box face, top-left corner at (x, y, z).
// Left faces run along +x (right-down), right faces along -y (right-up).
function isoLeftFace(x: number, y: number, z: number, k: number) {
  return `matrix(${0.866 * k} ${0.5 * k} 0 ${k} ${iso(x, y, z)})`;
}

function isoRightFace(x: number, y: number, z: number, k: number) {
  return `matrix(${0.866 * k} ${-0.5 * k} 0 ${k} ${iso(x, y, z)})`;
}

// Box from (x, y, z) with size w×d×h; only the top, left and right faces are visible.
// Solid boxes get an opaque base under the faces so tinted fills hide what is behind.
function IsoBox({
  x,
  y,
  z = 0,
  w,
  d,
  h,
  top,
  left,
  right,
  solid = true,
}: {
  x: number;
  y: number;
  z?: number;
  w: number;
  d: number;
  h: number;
  top: string;
  left: string;
  right: string;
  solid?: boolean;
}) {
  const zt = z + h;
  const faces = [
    [top, [iso(x, y, zt), iso(x + w, y, zt), iso(x + w, y + d, zt), iso(x, y + d, zt)]],
    [left, [iso(x, y + d, zt), iso(x + w, y + d, zt), iso(x + w, y + d, z), iso(x, y + d, z)]],
    [right, [iso(x + w, y, zt), iso(x + w, y + d, zt), iso(x + w, y + d, z), iso(x + w, y, z)]],
  ] as const;

  return (
    <>
      {solid && (
        <path
          d={`M${faces[1][1][3]} L${faces[0][1][3]} L${faces[0][1][0]} L${faces[0][1][1]} L${faces[2][1][3]} L${faces[1][1][2]} Z`}
          className="fill-canvas stroke-none"
        />
      )}
      {faces.map(([className, points]) => (
        <path key={className + points[0]} d={`M${points.join(" L")} Z`} className={className} />
      ))}
    </>
  );
}

// Terraform drops a new tenant account into an AWS Organization split into Core and Tenants OUs.
function LandingZone() {
  const size = 18;
  const core = [12, 34, 56].map((y) => ({ x: 17, y }));
  const tenants = [62, 88, 114].flatMap((x) => [20, 48].map((y) => ({ x, y })));
  const next = { x: 114, y: 20 };
  const coreFaces = {
    top: `${edge} fill-surface-raised`,
    left: `${edge} fill-surface`,
    right: `${edge} fill-canvas`,
  };
  const tenantFaces = {
    top: "fill-accent/25 stroke-accent/80",
    left: "fill-accent/15 stroke-accent/80",
    right: "fill-accent/[0.08] stroke-accent/80",
  };
  // Back to front, so nearer cubes cover the ones behind.
  const cubes = [
    ...core.map((c) => ({ ...c, kind: "core" })),
    ...tenants.map((c) => ({
      ...c,
      kind: c.x === next.x && c.y === next.y ? "next" : "tenant",
    })),
  ].sort((a, b) => a.x + a.y - (b.x + b.y));

  return (
    <>
      <IsoBox
        x={0}
        y={0}
        z={-18}
        w={150}
        d={84}
        h={18}
        top={`${line} fill-ink/[0.03]`}
        left={`${line} fill-surface`}
        right={`${line} fill-canvas`}
      />
      <g transform={`matrix(0.866 0.5 0 1 ${iso(10, 84, 4)})`}>
        <path d={awsTextPath} fillRule="evenodd" className="fill-ink/60 stroke-none" />
        <path d={awsSmilePath} fillRule="evenodd" className="fill-accent stroke-none" />
      </g>

      <path
        d={`M${iso(8, 6)} L${iso(44, 6)} L${iso(44, 80)} L${iso(8, 80)} Z`}
        className={`${faint} [stroke-dasharray:3_3]`}
      />
      <path
        d={`M${iso(52, 6)} L${iso(142, 6)} L${iso(142, 80)} L${iso(52, 80)} Z`}
        className="stroke-accent/30 [stroke-dasharray:3_3]"
      />

      {cubes.map((c) =>
        c.kind === "next" ? (
          <g key="next">
            <IsoBox
              {...c}
              w={size}
              d={size}
              h={size}
              solid={false}
              top="stroke-accent/70 [stroke-dasharray:2_2]"
              left="stroke-accent/70 [stroke-dasharray:2_2]"
              right="stroke-accent/70 [stroke-dasharray:2_2]"
            />
            <g className="opacity-0 group-hover/project:motion-safe:animate-drop">
              <IsoBox {...c} w={size} d={size} h={size} {...tenantFaces} />
            </g>
          </g>
        ) : (
          <IsoBox
            key={`${c.x}-${c.y}`}
            {...c}
            w={size}
            d={size}
            h={size}
            {...(c.kind === "core" ? coreFaces : tenantFaces)}
          />
        ),
      )}

      <path d="M212.4 58 V98" className={dashed} />
      <g transform="translate(198 25.6) scale(1.2)">
        <path d={terraformPath} className="fill-accent stroke-none" />
      </g>
    </>
  );
}

