// Host walled in on every side but one gate: NGINX. Requests go through it to Wiki.js, and only
// Wiki.js reaches PostgreSQL on the internal data network; Grafana watches from the monitor network.
function DocsStack() {
  const wiki = { x: 98, y: 27, s: 30 };
  const db = { x: 18, y: 10, s: 24 };
  const grafana = { x: 18, y: 50, s: 24 };
  const center = (c: typeof wiki) => [c.x + c.s / 2, c.y + c.s / 2] as const;
  const internalFaces = {
    top: `${edge} fill-surface-raised`,
    left: `${edge} fill-surface`,
    right: `${edge} fill-canvas`,
  };
  const appFaces = {
    top: "fill-accent/25 stroke-accent/80",
    left: "fill-accent/15 stroke-accent/80",
    right: "fill-accent/[0.08] stroke-accent/80",
  };
  const wall = {
    top: `${line} fill-surface-raised`,
    left: `${line} fill-surface`,
    right: `${line} fill-canvas`,
  };
  // Requests travel along y = 42 through the gate gap (y 28..56) into Wiki.js, then on to PostgreSQL.
  const travel = (from: [number, number, number], to: [number, number, number]) => {
    const [x1, y1] = isoPoint(...from);
    const [x2, y2] = isoPoint(...to);
    const style = { "--dx": `${x2 - x1}px`, "--dy": `${y2 - y1}px` } as React.CSSProperties;
    return { cx: x1, cy: y1, style };
  };
  const request = travel([200, 42, 3], [wiki.x + wiki.s, 42, 3]);
  const query = travel([wiki.x, 36, 3], [db.x + db.s, 24, 3]);
  const packet =
    "fill-accent stroke-none opacity-0 group-hover/project:motion-safe:animate-request";

  return (
    <>
      <IsoBox
        x={0}
        y={0}
        z={-18}
        w={150}
        d={84}
        h={18}
        top={`${line} fill-ink/[0.03]`}
        left={`${line} fill-surface`}
        right={`${line} fill-canvas`}
      />

      {/* Back walls */}
      <IsoBox x={0} y={0} w={150} d={3} h={7} {...wall} />
      <IsoBox x={0} y={3} w={3} d={81} h={7} {...wall} />

      {/* Networks: app reaches out through the gate; data and monitor are internal */}
      <path
        d={`M${iso(64, 8)} L${iso(142, 8)} L${iso(142, 78)} L${iso(64, 78)} Z`}
        className="stroke-accent/30 [stroke-dasharray:3_3]"
      />
      <path d={`M${iso(8, 6)} L${iso(54, 6)} L${iso(54, 40)} L${iso(8, 40)} Z`} className={faint} />
      <path d={`M${iso(8, 46)} L${iso(54, 46)} L${iso(54, 78)} L${iso(8, 78)} Z`} className={faint} />

      <path d={`M${iso(...center(db))} L${iso(...center(wiki))}`} className={line} />
      <path
        d={`M${iso(...center(grafana))} L${iso(...center(wiki))} M${iso(...center(grafana))} L${iso(...center(db))}`}
        className={dashed}
      />

      <IsoBox x={db.x} y={db.y} w={db.s} d={db.s} h={db.s} {...internalFaces} />
      <g transform={isoRightFace(db.x + db.s, db.y + db.s - 3, db.s - 3, 0.75)}>
        <path d={postgresqlPath} className="fill-ink/60 stroke-none" />
      </g>
      <IsoBox x={grafana.x} y={grafana.y} w={grafana.s} d={grafana.s} h={grafana.s} {...internalFaces} />
      <g transform={isoLeftFace(grafana.x + 3, grafana.y + grafana.s, grafana.s - 3, 0.75)}>
        <path d={grafanaPath} className="fill-ink/60 stroke-none" />
      </g>

      <circle r={3} {...query} className={packet} style={{ ...query.style, animationDelay: "1.2s" }} />

      <IsoBox x={wiki.x} y={wiki.y} w={wiki.s} d={wiki.s} h={wiki.s} {...appFaces} />
      <g transform={isoLeftFace(wiki.x + 4.2, wiki.y + wiki.s, wiki.s - 4.2, 0.9)}>
        <path d={wikijsPath} className="fill-ink/80 stroke-none" />
      </g>

      {/* The only way in: from outside, through the gate, to Wiki.js */}
      <path d={`M${iso(200, 42)} L${iso(wiki.x + wiki.s, 42)}`} className={dashed} />

      {/* Front walls, with the gate gap at y 28..56 */}
      <IsoBox x={3} y={81} w={147} d={3} h={7} {...wall} />
      <IsoBox x={147} y={3} w={3} d={25} h={7} {...wall} />
      <IsoBox x={147} y={56} w={3} d={25} h={7} {...wall} />

      {/* Gate: two posts and a lintel carrying the NGINX mark */}
      <IsoBox x={147} y={28} w={5} d={5} h={20} {...wall} />
      <IsoBox x={147} y={51} w={5} d={5} h={20} {...wall} />
      <IsoBox x={147} y={28} z={20} w={5} d={28} h={14} {...internalFaces} />
      <g transform={isoRightFace(152, 48, 33, 0.5)}>
        <path
          d={nginxPath}
          className="fill-ink/60 stroke-none transition-[fill] duration-300 group-hover/project:fill-accent"
        />
      </g>

      <circle r={3} {...request} className={packet} />
    </>
  );
}

